INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('steinway', 'Steinway & Sons', '', 'grand', NULL, 'europe', '6'' 2"', NULL, '#1b1b1d', 'Ebony Black', 'שחור', 147, 100, 188, 'A Steinway & Sons grand is the benchmark by which all other pianos are measured — hand-built with the tone, power, and touch that have made it the choice of the world''s great concert halls. This example has been carefully restored in our Jerusalem workshop, preserving its singing sustain and wide dynamic range. An instrument of a lifetime for the pianist who wants the very best.', 'פסנתר כנף של סטיינווי אנד סאנס הוא אמת המידה שלפיה נמדדים כל שאר הפסנתרים — בנוי בעבודת יד עם הצליל, העוצמה והנגיעה שהפכו אותו לבחירתם של אולמות הקונצרטים הגדולים בעולם. הכלי שוקם בקפידה בסדנה שלנו בירושלים, תוך שמירה על הסאסטיין השר והטווח הדינמי הרחב שלו. כלי של פעם בחיים לפסנתרן המבקש את המיטב שבמיטב.', 'Since 1853 Steinway & Sons has held more than a hundred patents that shaped the modern piano, and its grands remain the overwhelming choice of the world''s concert stages. Each instrument is built from thousands of individually crafted parts around Steinway''s patented rim and soundboard, producing the singing sustain, colour, and dynamic range that define the brand. Restored in our Jerusalem workshop, this grand offers the responsiveness and tonal depth that reward a lifetime of playing.', 'מאז 1853 מחזיקה סטיינווי אנד סאנס ביותר ממאה פטנטים שעיצבו את הפסנתר המודרני, ופסנתרי הכנף שלה נותרים הבחירה המובהקת של במות הקונצרטים בעולם. כל כלי נבנה מאלפי חלקים מעובדים בנפרד סביב המסגרת ולוח התהודה הפטנטיים של סטיינווי, ומפיק את הסאסטיין השר, הצבע והטווח הדינמי המגדירים את המותג. לאחר שיקום בסדנה שלנו בירושלים, פסנתר כנף זה מציע את הרספונסיביות והעומק הצלילי המתגמלים נגינה של חיים שלמים.', 0, 0);
