INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('bluthner', 'Blüthner', 'Model 6', 'grand', NULL, 'europe', '6'' 3"', NULL, '#1b1b1d', 'Ebony Black', 'שחור', 147, 100, 190, 'This Blüthner Model 6 grand was built in Leipzig around 1920, in the golden age of the celebrated German house founded in 1853. At 190 cm it delivers a warm, singing tone with clarity across every register and the light, responsive touch Blüthner is famed for, owed in part to its patented Aliquot stringing. Equally suited to delicate passages and powerful climaxes, it is a distinguished European instrument currently undergoing full restoration in our workshop and is not yet available for sale.', 'פסנתר הכנף הזה, בלוטנר דגם 6, נבנה בלייפציג סביב שנת 1920, בתור הזהב של בית המלאכה הגרמני הנודע שנוסד ב-1853. באורך 190 ס"מ הוא מפיק צליל חם ושר עם צלילות בכל הרגיסטרים ונגיעה קלה ורספונסיבית שבלוטנר מפורסמת בה, בין היתר בזכות מיתור ה-Aliquot הפטנטי. מתאים באותה מידה לקטעים עדינים ולשיאים עוצמתיים, זהו כלי אירופי מכובד הנמצא כעת בשיקום מלא בסדנה שלנו ואינו מוצע עדיין למכירה.', 'Julius Blüthner founded his Leipzig workshop in 1853, and by 1900 Blüthner was among the largest and most respected piano makers in the world, chosen by Brahms, Debussy, and Rachmaninoff. The firm''s signature Aliquot stringing adds a sympathetic fourth string in the treble that enriches the tone with a warm, golden shimmer unique to the brand. Currently undergoing full restoration in our workshop, this Model 6 will offer the light action and singing, romantic voice for which Blüthner grands are treasured.', 'יוליוס בלוטנר ייסד את בית המלאכה שלו בלייפציג ב-1853, ועד 1900 הייתה בלוטנר בין יצרני הפסנתרים הגדולים והמכובדים בעולם, ונבחרה על ידי ברהמס, דביסי ורחמנינוב. מיתור ה-Aliquot הייחודי של החברה מוסיף מיתר רביעי אוהד באזור הטרבל המעשיר את הצליל בברק זהוב וחם הייחודי למותג. הכלי נמצא כעת בשיקום מלא בסדנה שלנו, וה-Model 6 הזה יציע את המכניקה הקלה ואת הצליל השר והרומנטי שבזכותם מוקירים את פסנתרי הכנף של בלוטנר.', 1, 1);
