INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('erard', 'Érard', '180', 'grand', NULL, 'europe', '5'' 11"', NULL, '#5b2a14', 'Mahogany', 'מהגוני', 150, 100, 180, 'This Érard is a rare French grand from around 1923, built by the storied Paris house that invented the double-escapement action still found in every modern piano. On its elegant 180 cm case it offers the deep basses and sparkling treble that make it ideal for the French repertoire — Chopin, Debussy, Ravel, and Poulenc. A genuine piece of musical history, it is currently being lovingly restored in our workshop and is not yet available for sale.', 'הארר הזה הוא פסנתר כנף צרפתי נדיר משנת 1923 לערך, מתוצרת בית המלאכה הפריזאי האגדי שהמציא את מנגנון הבריחה הכפולה המצוי עד היום בכל פסנתר מודרני. בגוף אלגנטי באורך 180 ס"מ הוא מציע את הבסים העמוקים והטרבל הנוצץ ההופכים אותו למושלם לרפרטואר הצרפתי — שופן, דביסי, ראוול ופולנק. פיסת היסטוריה מוזיקלית אמיתית, הנמצאת כעת בתהליך שיקום מוקפד בסדנה שלנו ואינה מוצעת עדיין למכירה.', 'Founded in Paris in 1780, the House of Érard supplied instruments to Liszt, Mendelssohn, Fauré, and Ravel, and its 1821 double-escapement action became the template for every grand piano that followed. Instruments of this era are cherished for their transparent, colourful tone and fine period cabinetry — qualities that make them ideal for Romantic and Impressionist French music. Our technicians are carefully restoring this Érard to preserve both its historic character and its playability, so it can once again be heard as its makers intended.', 'בית ארר, שנוסד בפריז ב-1780, סיפק כלים לליסט, מנדלסון, פורה וראוול, ומנגנון הבריחה הכפולה שלו משנת 1821 הפך לתבנית לכל פסנתר כנף שבא אחריו. כלים מתקופה זו נערצים בזכות צלילם השקוף ועתיר הצבע ובזכות נגרות התקופה המעודנת שלהם — תכונות ההופכות אותם למושלמים למוזיקה הצרפתית הרומנטית והאימפרסיוניסטית. הטכנאים שלנו משקמים בקפידה את הארר הזה כדי לשמר הן את אופיו ההיסטורי והן את נגישותו לנגינה, כך שיישמע שוב כפי שיוצריו התכוונו.', 1, 2);
