INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('yamaha-grand', 'Yamaha', 'C3', 'grand', NULL, 'japan', '6'' 1"', NULL, '#1b1b1d', 'Ebony Black', 'שחור', 148, 101, 186, 'The Yamaha C3 is a 186 cm conservatory grand and one of the most popular instruments of its size in the world — the go-to choice of studios, schools, and serious homes for its powerful, focused sound, dependable mechanics, and excellent tuning stability. Japanese-built and fully serviced in our workshop, it offers a clear tone and an even, responsive action across the whole keyboard. A versatile grand equally at home in classical, jazz, and contemporary playing.', 'ה-C3 של ימאהה הוא פסנתר כנף קונצרטי באורך 186 ס"מ ואחד הכלים הפופולריים ביותר בגודלו בעולם — הבחירה המועדפת של אולפנים, בתי ספר ובתים רציניים בזכות הצליל העוצמתי והממוקד, המכניקה האמינה ויציבות הכיוונון המצוינת. מתוצרת יפן ולאחר טיפול מלא בסדנה שלנו, הוא מציע צליל צלול ומכניקה אחידה ורספונסיבית לאורך כל הקלידים. פסנתר כנף רב-תכליתי, בבית באותה מידה בנגינה קלאסית, ג׳אז ומוזיקה עכשווית.', 'The C3 belongs to Yamaha''s acclaimed C (Conservatory) series and has passed through several generations of refinement since the early 1970s, earning a reputation as the reliable, all-round six-foot grand. Its scale design delivers a clear, projecting tone with a firm bass and singing treble, and the precise Yamaha action makes it a favourite for classical study, jazz, and recording alike. Built in Japan and fully serviced by our team, this C3 is an ideal first grand for a school, studio, or serious home.', 'ה-C3 שייך לסדרת ה-C (קונסרבטורי) המהוללת של ימאהה ועבר מספר דורות של שכלול מאז תחילת שנות ה-70, וזכה למוניטין של פסנתר הכנף בגודל שש רגל האמין והרב-תכליתי. תכן הסקייל שלו מספק צליל צלול ומקרין עם בס איתן וטרבל שר, והמכניקה המדויקת של ימאהה הופכת אותו למועדף ללימוד קלאסי, ג׳אז והקלטות כאחד. מתוצרת יפן ולאחר טיפול מלא על ידי הצוות שלנו, ה-C3 הוא פסנתר כנף ראשון אידיאלי לבית ספר, אולפן או בית רציני.', 0, 3);
