INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('yamaha-ux', 'Yamaha', 'UX', 'upright', NULL, 'japan', '52"', 32000, '#1b1b1d', 'Ebony Black', 'שחור', 154, 131, 65, 'The Yamaha UX is the professional flagship of Yamaha''s upright line, recognised by its distinctive X-braced back and grand-piano-grade action and soundboard materials. Made in Japan and standing 131 cm tall, it delivers longer bass strings and superior tuning stability, producing a powerful, resonant tone sought after by concert-level players. Fully serviced in our Jerusalem workshop, this UX is a rare and rewarding instrument for the discerning musician.', 'ה-UX של ימאהה הוא דגל הדגם המקצועי בסדרת הפסנתרים הזקופים של ימאהה, המזוהה בגב מחוזק ה-X ובחומרי מכניקה ולוח תהודה ברמת פסנתר כנף. מתוצרת יפן ובגובה 131 ס"מ, הוא מספק מיתרי בס ארוכים יותר ויציבות כיוונון מעולה, ומפיק צליל עוצמתי ומהדהד המבוקש על ידי נגנים ברמת קונצרט. לאחר טיפול מלא בסדנה שלנו בירושלים, ה-UX הוא כלי נדיר ומתגמל למוזיקאי הבררן.', 'Produced between 1976 and 1980, the UX introduced Yamaha''s distinctive wooden X-shaped back brace, borrowed from grand-piano design to add rigidity and tonal stability. Combined with longer bass strings routed over a curved bridge and higher-grade hammer felt, this gives the UX a warmer, more complex voice than the standard U-series. Now relatively rare and prized by collectors and professionals alike, this fully serviced example offers concert-level tone in an upright cabinet.', 'ה-UX יוצר בין 1976 ל-1980 והציג את גב ה-X העשוי עץ הייחודי של ימאהה, ששאול מעולם פסנתרי הכנף כדי להוסיף קשיחות ויציבות צלילית. יחד עם מיתרי בס ארוכים יותר המונחים על גשר מעוקל ולבד פטישים באיכות גבוהה, מעניק הדבר ל-UX צליל חם ומורכב יותר מסדרת ה-U הרגילה. כיום נדיר יחסית ומוערך על ידי אספנים ואנשי מקצוע כאחד, הכלי המטופל במלואו מציע צליל ברמת קונצרט בארון של פסנתר זקוף.', 0, 4);
