INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('kawai-ns35', 'Kawai', 'NS-35', 'upright', '1642672', 'japan', '52"', 22000, '#1b1b1d', 'Ebony Black', 'שחור', 153, 132, 61, 'The Kawai NS-35 sits at the top of Kawai''s acclaimed NS series — a professional 132 cm upright built with premium materials for a rich, dynamic tone and generous bass. Made in Japan and finished in polished ebony, this instrument has been fully restored and regulated in our Jerusalem workshop. Tall, powerful, and beautifully balanced, it rewards advanced players who want an upright with real depth.', 'ה-NS-35 של קאוואי ניצב בראש סדרת ה-NS המהוללת — פסנתר זקוף מקצועי בגובה 132 ס"מ, הבנוי מחומרים מובחרים לצליל עשיר ודינמי ובס נדיב. מתוצרת יפן ובגימור אבונית מלוטשת, הכלי שוקם וכוונן במלואו בסדנה שלנו בירושלים. גבוה, עוצמתי ומאוזן להפליא, הוא מתגמל נגנים מתקדמים המחפשים פסנתר זקוף בעל עומק אמיתי.', 'The NS-35 was the top model of Kawai''s NS series, produced from the mid-1980s to the mid-1990s and built to professional ''artist'' standards with premium materials throughout. At 132 cm it is among the tallest uprights Kawai made, and its extra string length and large soundboard yield a powerful, dynamic tone with a full, warm bass. Marketed mainly in Japan, the NS-35 is now sought after abroad; this fully restored example offers grand-like scale and depth in an upright footprint.', 'ה-NS-35 היה הדגם העליון בסדרת ה-NS של קאוואי, שיוצרה מאמצע שנות ה-80 עד אמצע שנות ה-90 ונבנתה בסטנדרט "אמן" מקצועי מחומרים מובחרים לכל אורכה. בגובה 132 ס"מ הוא מהגבוהים שבפסנתרים הזקופים שקאוואי ייצרה, ואורך המיתרים הנוסף ולוח התהודה הגדול מפיקים צליל עוצמתי ודינמי עם בס מלא וחם. הדגם שווק בעיקר ביפן ומבוקש כיום גם מחוצה לה; הכלי המשוקם במלואו מציע ממדים ועומק דמויי כנף בתצורת פסנתר זקוף.', 0, 5);
INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('piano', 'kawai-ns35', '/images/shop/kawai-ns35/kawai-ns35-0.webp', 0, NULL, NULL);
