INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('kawai-cx21', 'Kawai', 'CX-21', 'upright', '2318158', 'japan', '48"', 18000, '#1b1b1d', 'Ebony Black', 'שחור', 152, 121, 60, 'The Kawai CX-21 is a professional 121 cm Japanese upright celebrated for its warm, round tone and responsive action — an excellent alternative to the Yamaha U-series for players who prefer a mellower voice. This example has been carefully reconditioned, regulated, and tuned in our workshop. Solidly built and dependable, it is well suited to the home, the teaching studio, or the practice room.', 'ה-CX-21 של קאוואי הוא פסנתר זקוף מקצועי יפני בגובה 121 ס"מ, הנודע בצליל החם והעגול ובמכניקה הרספונסיבית שלו — חלופה מצוינת לסדרת ה-U של ימאהה עבור מי שמעדיף צליל רך יותר. הכלי שוקם, כוונן וכויּן בקפידה בסדנה שלנו. בנוי היטב ואמין, הוא מתאים לבית, לסטודיו להוראה או לחדר התרגול.', 'Kawai built the CX-21 in the late 1980s and early 1990s as a professional-grade competitor to the Yamaha U1, and it remains a favourite for its warm, singing tone and quiet, even action. Careful scaling and a solid spruce soundboard produce a rounder, less bright sound that many pianists find easier to listen to over long sessions. Reconditioned in our workshop, this CX-21 is a dependable, characterful choice for the home or teaching studio.', 'קאוואי ייצרה את ה-CX-21 בסוף שנות ה-80 ותחילת שנות ה-90 כמתחרה מקצועי ל-U1 של ימאהה, והוא נותר מועדף בזכות צלילו החם והשר ומכניקה שקטה ואחידה. סקיילינג קפדני ולוח תהודה מאשוח מלא מפיקים צליל עגול ופחות חד, שרבים מוצאים נעים יותר להאזנה לאורך זמן. לאחר שיפוץ בסדנה שלנו, ה-CX-21 הוא בחירה אמינה ובעלת אופי לבית או לסטודיו להוראה.', 0, 6);
