INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('yamaha-u3-3091140', 'Yamaha', 'U3', 'upright', '3091140', 'japan', '52"', 27000, '#1b1b1d', 'Ebony Black', 'שחור', 153, 131, 65, 'The Yamaha U3 is the taller, fuller-voiced sibling of the U1 — at 131 cm its longer strings and larger soundboard give a deeper bass and richer sustain. A favourite of teachers, conservatories, and advanced pianists, this Japanese-made instrument has been meticulously restored and regulated in our workshop. It offers close to grand-piano presence in an upright footprint, ready for years of demanding daily playing.', 'ה-U3 של ימאהה הוא האח הגבוה ובעל הצליל המלא יותר של ה-U1 — בגובה 131 ס"מ, המיתרים הארוכים והלוח הגדול יותר מעניקים בס עמוק וסאסטיין עשיר יותר. מועדף על מורים, קונסרבטוריונים ופסנתרנים מתקדמים, הכלי מתוצרת יפן שוקם וכוונן בקפידה בסדנה שלנו. הוא מציע נוכחות הקרובה לזו של פסנתר כנף במידות של פסנתר זקוף, ומוכן לשנים של נגינה יומית תובענית.', 'The U3 has been Yamaha''s flagship 52-inch upright since 1927 — the taller cousin of the U1, chosen by conservatories and professionals who want more power and a deeper bass. Its longer strings and larger soundboard produce a broad, resonant sound that fills a room, and the celebrated Yamaha action allows fast, controlled repetition. Imported from Japan and fully reconditioned, this U3 offers near-recital projection while remaining perfectly at home in a serious practice studio.', 'ה-U3 הוא דגל הפסנתרים הזקופים בגובה 52 אינץ'' של ימאהה מאז 1927 — בן הדוד הגבוה של ה-U1, שנבחר על ידי קונסרבטוריונים ואנשי מקצוע הזקוקים לעוצמה רבה יותר ולבס עמוק יותר. המיתרים הארוכים ולוח התהודה הגדול יוצרים צליל רחב ומהדהד הממלא את החדר, והמכניקה הנודעת של ימאהה מאפשרת חזרתיות מהירה ומבוקרת. לאחר יבוא מיפן ושיפוץ מלא, ה-U3 מספק הקרנה קרובה לזו של אולם, ובה בעת מרגיש בבית באולפן תרגול רציני.', 0, 7);
