INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('piano', 'yamaha-u3-3493455', '/images/shop/yamaha-u3-3493455/yamaha-u3-3493455-7.webp', 7, NULL, NULL);
INSERT INTO pianos (id, brand, model, type, serial, region, size, price_ils, color_hex, color_name_en, color_name_he, dim_width, dim_height, dim_depth, description_en, description_he, details_en, details_he, wip, sort_order) VALUES ('yamaha-u1-2262061', 'Yamaha', 'U1', 'upright', '2262061', 'japan', '48"', 20000, '#1b1b1d', 'Ebony Black', 'שחור', 153, 121, 61, 'The Yamaha U1 is the world''s most trusted professional upright — a 121 cm instrument prized for its even touch, clear projection, and remarkable reliability. Built in Japan, this example has been fully inspected, regulated, and voiced in our Jerusalem workshop so it plays with the focused, singing tone Yamaha uprights are loved for. Compact enough for the home yet powerful enough for the studio, the U1 is an ideal choice for students and serious players alike.', 'ה-U1 של ימאהה הוא הפסנתר הזקוף המקצועי המוכר בעולם — כלי בגובה 121 ס"מ המוערך על נגיעה אחידה, הקרנה צלולה ואמינות יוצאת דופן. הכלי, מתוצרת יפן, עבר בדיקה, כיוונון ווויסות מלאים בסדנה שלנו בירושלים, כך שהוא מנגן בצליל הממוקד והשר שבזכותו נאהבים הפסנתרים הזקופים של ימאהה. קומפקטי מספיק לבית אך עוצמתי מספיק לאולפן — ה-U1 הוא בחירה אידיאלית לתלמידים ולנגנים רציניים כאחד.', 'First introduced in 1927, the U1 has been refined over nearly a century into the definitive studio upright, with hundreds of thousands built. Its full-length strings and solid spruce soundboard give a bigger sound than its compact cabinet suggests, while the renowned Yamaha action stays precise for decades. Imported from Japan and reconditioned for our climate, this instrument holds its tuning beautifully and serves equally well for daily practice or performance preparation.', 'ה-U1 הוצג לראשונה ב-1927 ולאורך כמעט מאה שנה עוצב והשתכלל לכדי הפסנתר הזקוף האולפני המוביל, במאות אלפי יחידות שנבנו. המיתרים במלוא אורכם ולוח התהודה מעץ אשוח מלא מפיקים צליל גדול מכפי שגודל הארון מרמז, בעוד המכניקה המהוללת של ימאהה נשארת מדויקת במשך עשורים. הכלי יובא מיפן ושופץ להתאמה לאקלים שלנו, שומר על כיוונו להפליא ומשרת נאמנה הן לתרגול יומי והן להכנה להופעות.', 0, 10);
