INSERT INTO concerts (id, name_en, name_he, date, time, venue_en, venue_he, price_ils, description_en, description_he, sort_order) VALUES ('misha-zartsekel', 'Michael Zartsekel', 'מישה זרצקל', '2026-12-14', '20:00', 'Ben Sira 3, Jerusalem', 'בן סירא 3, ירושלים', 90, 'Michael (Misha) Zartsekel is one of the leading Israeli pianists of his generation, born in Rostov, Russia, and immigrating to Israel on his own at a young age. He began playing at the age of seven and, by ten, had been admitted to Moscow''s prestigious Tchaikovsky school for gifted young musicians. He has won a string of international prizes, among them first prize at the Scriabin Competition in Moscow and at the piano competition of the Jerusalem Academy of Music. Zartsekel performs as a soloist with Israel''s foremost symphony orchestras and appears frequently in recitals and festivals both in Israel and abroad. In this intimate recital he brings a sweeping classical program — a rare evening of virtuosity and feeling, up close.', 'מיכאל (מישה) זַרְצֶקֶל הוא מן הפסנתרנים הישראלים המובילים בדורו, יליד רוסטוב שברוסיה שעלה לישראל בגפו בגיל צעיר. את נגינתו החל בגיל שבע, וכבר בגיל עשר התקבל לבית הספר היוקרתי למחוננים על שם צ׳ייקובסקי במוסקבה. הוא זכה בשורה של תחרויות בין-לאומיות, ובהן הפרס הראשון בתחרות על שם סקריאבין במוסקבה ובתחרות הפסנתר של האקדמיה למוסיקה בירושלים. זרצקל מופיע כסולן עם התזמורות הסימפוניות המובילות בישראל ומרבה לנגן ברסיטלים ובפסטיבלים בארץ ובעולם. ברסיטל אינטימי זה יביא זרצקל תוכנית קלאסית סוחפת — ערב נדיר של וירטואוזיות ורגש, במרחק נגיעה.', 0);
INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('concert', 'misha-zartsekel', '/images/Concerts/misha-zartsekel.png', 0, 'Michael Zartsekel', 'מישה זרצקל');
