INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('soundboard-restoration', 'restoration', 'Soundboard Restoration', 'שיקום לוח תהודה', 'Repairing cracks and restoring the soundboard to preserve sound quality.', 'תיקון סדקים ושיקום לוח התהודה לשימור איכות הצליל.', 1);
INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('restringing', 'restoration', 'Restringing', 'החלפת מיתרים', 'Complete replacement of the piano''s strings to improve tone quality and performance.', 'החלפה מלאה של מיתרי הפסנתר לשיפור איכות הצליל והביצועים.', 2);
