INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('tuning-pin-replacement', 'restoration', 'Tuning Pin Replacement', 'החלפת ברגי כיוון', 'Replacing the tuning pins to improve string grip and tuning stability.', 'החלפת ברגי הכיוון לשיפור אחיזת המיתרים ויציבות הכיוון.', 4);
INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('hammer-restoration', 'restoration', 'Hammer Restoration & Replacement', 'שיקום והחלפת פטישים', 'Restoring, shaping or replacing hammers for a balanced, rich tone.', 'שיקום, עיצוב או החלפת פטישים לקבלת צליל מאוזן ועשיר.', 5);
INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('keyboard-restoration', 'restoration', 'Keyboard Restoration', 'תיקוני מקלדת', 'Replacing key coverings, polishing ivory and restoring the look and feel of the keyboard.', 'החלפת ציפויי קלידים, פוליש שנהב ושיקום מראה ותחושת הנגינה.', 6);
INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('damper-restoration', 'restoration', 'Damper Restoration', 'שיקום מערכת האוטמים', 'Restoring and regulating the damper system for quiet, precise operation.', 'שיקום וכיוון מערכת האוטמים לפעולה שקטה ומדויקת.', 7);
INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('pedal-restoration', 'restoration', 'Pedal Restoration', 'שיקום מנגנון הדוושות', 'Repairing and regulating the pedal mechanism to restore smooth, precise operation.', 'תיקון וכיוון מנגנון הדוושות להחזרת פעולה חלקה ומדויקת.', 8);
INSERT INTO workshop_services (id, category_id, name_en, name_he, description_en, description_he, sort_order) VALUES ('cabinet-restoration', 'restoration', 'Cabinet Restoration', 'שיקום וגימור גוף הפסנתר', 'Veneer, paint and French-polish work to restore the piano''s original appearance.', 'תיקוני פורניר, צבע ופוליטורה להחזרת מראהו המקורי של הפסנתר.', 9);
