INSERT INTO about_sections (key, title_en, title_he, body_en, body_he, sort_order) VALUES ('studio', 'The Studio', 'הסטודיו', '["Trio was founded out of a love for the piano and the craftsmanship behind it. We believe that a fine instrument is much more than a piece of furniture or a product. It is a living thing, shaped by its materials, its environment, the way it is played and the passage of time. Each piano requires its own kind of attention, patience and precision.","Every piano that comes through Trio is restored, tuned and cared for by our own hands, with close attention to its tone, touch, mechanics and finish. The studio itself was built entirely by us, from the walls to the woodwork, with the same care and attention we bring to every instrument. Our goal was to create a place that feels as good to work in as it does to play and spend time in.","But Trio is more than a workshop. We wanted to create a place where craftsmanship and music naturally come together. Alongside our restoration work, we host piano concerts and cultural events that celebrate the piano and the music around it, giving people the opportunity to experience the instrument, the craft behind it and the people who dedicate their lives to it, all under one roof, in the heart of Jerusalem."]', '["טריו הוקם מתוך אהבה לפסנתר ולמלאכה שמאחוריו, מתוך אמונה שכלי נגינה טוב הוא הרבה יותר מרהיט או מוצר. הוא יצור חי, שמגיב לחומר, לסביבה, למגע ולזמן, וכל אחד מהם דורש הקשבה, סבלנות ודיוק בדרך שונה.","כל פסנתר שעובר בטריו משופץ, מכוון ומטופל בידיים שלנו, תוך הקפדה על איכות הצליל, דיוק המנגנון, הנראות והגימור. באותה רוח גם הסטודיו כולו נבנה בידיים שלנו, מהקירות ועד עבודות העץ, מתוך רצון ליצור מקום שנעים לעבוד בו, לנגן בו ולהיות בו.","אבל טריו הוא לא רק בית מלאכה. רצינו ליצור מקום שמחבר בין המלאכה לבין המוזיקה עצמה. לצד עבודת השיפוץ מתקיימים אצלנו קונצרטים ואירועי תרבות סביב עולם הפסנתר והמוסיקה, כדי לאפשר לקהל הרחב להכיר מקרוב את הכלי, את המלאכה שמאחוריו ואת האנשים שמקדישים את חייהם אליו, תחת קורת גג אחת, בלב ירושלים."]', 0);
INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('about_section', 'studio', '/images/About/about-trio.jpg', 0, NULL, NULL);
INSERT INTO about_sections (key, title_en, title_he, body_en, body_he, sort_order) VALUES ('who', 'Who We Are', 'מי אנחנו', '["Trio was founded by three friends who met while studying at the Jerusalem Academy of Music and Dance.","All three of us are graduates of the Academy and former Outstanding Musicians in the IDF. Since then, each of us has continued to build a career around the piano from a different perspective.","Over the years we''ve worked as performers, teachers, piano technicians and craftsmen, continually expanding our knowledge of piano restoration, rebuilding and conservation. Our work combines musical understanding with meticulous craftsmanship, with the goal of bringing back the unique character, touch and sound of every piano.","Trio is where these three worlds naturally come together: craftsmanship, music and a lifelong friendship, all rooted in Jerusalem."]', '["טריו הוקם על ידי שלושה חברים שהכירו במהלך לימודיהם באקדמיה למוזיקה ולמחול בירושלים.","שלושתנו בוגרי האקדמיה, מוזיקאים מצטיינים בצה”ל, וכולנו בחרנו להמשיך את דרכנו המקצועית סביב הפסנתר, כל אחד מזווית מעט אחרת.","עם השנים צברנו ניסיון כפסנתרנים, מורים, מכווני פסנתרים ואנשי מלאכה, והמשכנו ללמוד ולהעמיק בתחום שיפוץ, שימור ובניית פסנתרים. העבודה שלנו משלבת ידע מוזיקלי עם עבודת יד מדויקת, במטרה להחזיר לכל פסנתר את האופי, התחושה והצליל הייחודיים לו.","טריו הוא החיבור הטבעי בין שלושת העולמות האלה, מלאכה, מוזיקה וחברות ארוכת שנים, בירושלים."]', 1);
INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('about_section', 'who', '/images/About/who-we-are.jpeg', 0, NULL, NULL);
INSERT INTO founders (id, name_en, name_he, bio_en, bio_he, sort_order) VALUES ('gadi', 'Gadi Milanez', 'גדי מילנז', 'Gadi Milanez holds a Bachelor''s degree in Piano Performance from the Jerusalem Academy of Music and Dance and served as an Outstanding Musician in the Israel Defense Forces. For more than 13 years, he has specialized in piano tuning, restoration and rebuilding, working alongside piano technicians in Israel and abroad. He has also completed professional training through the Randy Potter School of Piano Technology, Bösendorfer training programs, and courses with some of the world''s leading piano tuners and restorers. Today, Gadi serves as the official piano technician of the Jerusalem Academy of Music and Dance.', 'גדי מילנז הוא בוגר תואר ראשון בביצוע בפסנתר מהאקדמיה למוזיקה ולמחול בירושלים ומוזיקאי מצטיין בצה”ל. הוא עוסק בכיוון, שיפוץ ושימור פסנתרים מזה למעלה מ־13 שנה, במהלכן למד ועבד עם מכווני פסנתרים בארץ ובעולם, והשתלם במסגרות מקצועיות שונות, בהן בית הספר של Randy Potter, השתלמויות של Bösendorfer וקורסים של מיטב המכוונים והמשפצים בעולם. כיום גדי הוא המכוון הרשמי של האקדמיה למוזיקה ולמחול בירושלים.', 0);
INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('founder', 'gadi', '/images/About/Gadi.jpg', 0, 'Gadi Milanez', 'גדי מילנז');
INSERT INTO founders (id, name_en, name_he, bio_en, bio_he, sort_order) VALUES ('nethanel', 'Nethanel Fastman', 'נתנאל פסטמן', 'Netanel Fastman holds both Bachelor''s and Master''s degrees in Piano Performance from the Jerusalem Academy of Music and Dance and served as an Outstanding Musician in the Israel Defense Forces. For more than a decade, he has specialized in piano tuning, restoration and rebuilding in Israel and abroad. He received his professional training through hands-on work in the workshop of renowned piano technician and restorer Zamir Havkin. Today, Netanel serves as a piano technician for leading institutions, including the Israel Arts and Science Academy (IASA), the Brigham Young University Jerusalem Center, and the Jerusalem Academy High School for Music and Dance.', 'נתנאל פסטמן הוא בוגר תואר ראשון ושני בביצוע בפסנתר מהאקדמיה למוזיקה ולמחול בירושלים ומוזיקאי מצטיין בצה”ל. מזה למעלה מעשור הוא עוסק בכיוון, שיפוץ ושימור פסנתרים בארץ ובעולם, ורכש את הכשרתו המקצועית בבית המלאכה של מכוון ומשפץ הפסנתרים זמיר חבקין. כיום הוא מכוון פסנתרים במוסדות מובילים, בהם בית הספר למדעים ולאמנויות יאסא, האוניברסיטה המורמונית ותיכון האקדמיה למוזיקה ולמחול בירושלים.', 1);
INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('founder', 'nethanel', '/images/About/Fastman.jpg', 0, 'Nethanel Fastman', 'נתנאל פסטמן');
INSERT INTO founders (id, name_en, name_he, bio_en, bio_he, sort_order) VALUES ('noam', 'Noam Shochat', 'נועם שוחט', 'Noam Shochat holds both Bachelor''s and Master''s degrees in Piano Performance from the Jerusalem Academy of Music and Dance and served as an Outstanding Musician in the Israel Defense Forces. Alongside his work as a pianist and teacher, he founded and managed cultural and hospitality businesses in Jerusalem, producing concerts, live performances and cultural events. He leads the connection between the workshop and its cultural life, combining his passion for the piano with his love for Jerusalem, the city where he grew as a musician.', 'נועם שוחט הוא בוגר תואר ראשון ושני בביצוע בפסנתר מהאקדמיה למוזיקה ולמחול בירושלים ומוזיקאי מצטיין בצה”ל. לצד פעילותו כפסנתרן ומורה, הקים וניהל עסקים בתחום התרבות וחיי הלילה בירושלים, תוך הפקת קונצרטים, הופעות ואירועי תרבות. הוא מוביל את החיבור בין עבודת הסטודיו לבין הפעילות המוזיקלית והתרבותית, מתוך אהבה גדולה לפסנתר ולעיר שבה גדל כמוזיקאי.', 2);
INSERT INTO images (entity_type, entity_id, url, sort_order, alt_en, alt_he) VALUES ('founder', 'noam', '/images/About/Noam.jpg', 0, 'Noam Shochat', 'נועם שוחט');
